# ============ write ============
Write-Payload 'MA.html' $B64_MA_html $SHA_MA_html
Write-Payload 'overrides.html' $B64_overrides_html $SHA_overrides_html
Write-Payload 'STATE.md' $B64_STATE_md $SHA_STATE_md

$ovNew = [IO.File]::ReadAllText("$ROOT\overrides.html", [Text.Encoding]::UTF8)
if ($ovNew -notmatch "_BUILD_VER='V670\.4'") { throw 'version bump missing after write' }
Write-Host "version on disk : $NEWVER" -ForegroundColor Green

Write-Host '' ; Write-Host 'clasp push -f ...' -ForegroundColor Cyan
clasp push -f
if ($LASTEXITCODE -ne 0) { throw 'clasp push failed' }
Write-Host 'clasp create-deployment ...' -ForegroundColor Cyan
clasp create-deployment -i $DEPID -d $MSG
if ($LASTEXITCODE -ne 0) { throw 'create-deployment failed' }

git add -A
git commit -m $MSG
git push

Write-Host ''
Write-Host "DONE : $NEWVER" -ForegroundColor Green
Write-Host 'user must Ctrl+Shift+R' -ForegroundColor Yellow
Stop-Transcript | Out-Null
